#include "cmark_gfm.h" // includes cmark_parser and cmark_node enum definitions.

// This function converts input markdown text to HTML format.
std::string markdownToHtml(std::string &markdown) {
    // Initialize parser and allocate memory for the parsed document.
    struct cmark_parser context{};
    context.input_buffer = const_cast<char*>(markdown.data());
    context.input_size = static_cast<cmark_size_t>(markdown.length());
    auto parser = cmark_parser_new(&context);

    struct cmark_node* node;
    int ret;
    std::string result;

    while ((ret = cmark_parser_parse(parser, 0))) {
        node = cmark_parser_final_node(parser);
